{
  "name": "soroi-install-check-library",
  "private": true,
  "type": "module",
  "dependencies": {
    "decimal.js": "latest"
  }
}

import { program } from "omp-soroi/node";
import Decimal from "decimal.js";

export default program(async (input: number) => new Decimal(input).mul(2).toNumber());

